shader_body
{

    //rotate texture cords
    float texRotU2 = (uv[0] - 0.5)*cos(-q8*0.29) + (uv[1] - 0.5)*sin(-q8*0.29);
    float texRotv2 = -(uv[0] - 0.5)*sin(-q8*0.29) + (uv[1] - 0.5)*cos(-q8*0.29);


	    vec2 uv2 = vec2(texRotU2*0.8 +0.5, texRotv2*0.8 + 0.5);

    vec2 uv_echo = (uv - 0.5)*1.000*vec2(-1.0,-1.0) + 0.5;
    ret = mix( texture(sampler_main, uv).xyz, 
                texture(sampler_main, uv_echo).xyz, 
                0.50 
              )*0.6;

    ret += texture(sampler_main, uv2).xyz*0.4;
    ret *= 2.00; //gamma
    ret = (1.0 - ret*(1.0-ret)*4.0)*0.6; //invert
}
